mapper.select:
    /* 마스터테이불 심사상세 정보  */
	SELECT (SELECT AI_INPT_CMN_CD_NM
		FROM CSPD112TI										/* 공통코드 테이블 */
	   WHERE AI_INPT_GRP_CD = '150'							/* AI_INPT_GRP_CD = '150' 심사자동화업무구분코드 */
		 AND AI_INPT_CMN_CD = A.INPT_ATMC_BIZ_DSCD			/* 공통코드 테이블 */
	 ) AS INPT_ATMC_BIZ_NM
	 FROM CSPD001TM A										/* 심사마스터 테이블 */
	WHERE A.INPT_MST_SRNO = #{inptMstSrno}

/* left tab */ SELECT X.INPT_MST_SRNO, /* 심사마스터일련번호 */ X.INPT_TASK_ID, /* 심사테스크아이디 */ X.INPT_BL_GRP_NO, /* 심사BL그룹번호 */ X.IMEX_HIS_CD, /* 수출입명세코드 */ Y.AI_INPT_CMN_CD_ENG_NM AS IMEX_HIS_NM, /* 수출입명세영문명 */ Y.AI_INPT_RMRK_TXT AS IMEX_HIS_ABBR, /* AI심사비고내용 */ X.INPT_ELMT_ID, Y.AI_INPT_SORT_SEQ, CASE WHEN Z.CNT > 0 THEN 'Y' ELSE 'N' END AS AI_INPT_ALT_YN /* AI심사ALERT유무 */ FROM ( SELECT INPT_MST_SRNO, /* 심사마스터일련번호 */ INPT_BL_GRP_NO, /* 심사BL그룹번호 */ IMEX_HIS_CD, /* 수출입명세코드 */ INPT_TASK_ID, /* 심사테스크아이디 */ INPT_ELMT_ID, /* 심사요소아이디 */ CASE WHEN IMEX_HIS_CD = '01' THEN 1 WHEN IMEX_HIS_CD = '02' THEN 2 WHEN IMEX_HIS_CD = '03' THEN 3 WHEN IMEX_HIS_CD = '04' THEN 4 WHEN IMEX_HIS_CD = '05' THEN 5 WHEN IMEX_HIS_CD = '06' THEN 6 WHEN IMEX_HIS_CD = '07' THEN 7 WHEN IMEX_HIS_CD = '08' THEN 8 WHEN IMEX_HIS_CD = '09' THEN 9 WHEN IMEX_HIS_CD = '10' THEN 10 WHEN IMEX_HIS_CD = '11' THEN 11 WHEN IMEX_HIS_CD = '12' THEN 12 WHEN IMEX_HIS_CD = '13' THEN 13 ELSE 99 END AS RNK , ROW_NUMBER() OVER (PARTITION BY INPT_BL_GRP_NO, IMEX_HIS_CD ORDER BY TO_NUMBER(INPT_TASK_ID)) AS RN FROM CSPD002TG /* 테스크테이블 */ WHERE INPT_MST_SRNO = #{inptMstSrno} ) X, CSPD112TI Y, /* 공통코드테이블 */ ( SELECT A.INPT_MST_SRNO, /* 심사마스터일련번호 */ A.INPT_BL_GRP_NO, /* 심사BL그룹번호 */ A.IMEX_HIS_CD, /* 수출입명세코드 */ COUNT(*) AS CNT FROM ( SELECT B.INPT_MST_SRNO, /* 심사마스터일련번호 */ B.INPT_TASK_ID, /* 심사테스크아이디 */ B.INPT_BL_GRP_NO , /* 심사BL그룹번호 */ B.IMEX_HIS_CD /* 수출입명세코드 */ FROM CSPD003TF A, /* TotalText심사테이블 */ CSPD002TG B /* 테스크테이블 */ WHERE A.INPT_MST_SRNO = #{inptMstSrno} AND A.INPT_MST_SRNO = B.INPT_MST_SRNO /* 심사마스터일련번호 */ AND A.INPT_TASK_ID = B.INPT_TASK_ID /* 심사테스크아이디 */ AND A.AI_INPT_ALT_YN = 'Y' /* AI심사ALERT유무 */
UNION ALL
SELECT B.INPT_MST_SRNO, /* 심사마스터일련번호 */ B.INPT_TASK_ID, /* 심사테스크아이디 */ B.INPT_BL_GRP_NO, /* 심사BL그룹번호 */ B.IMEX_HIS_CD /* 수출입명세코드 */ FROM CSPD004TF A, /* 항목심사테이블 */ CSPD002TG B /* 테스크테이블 */ WHERE A.INPT_MST_SRNO = #{inptMstSrno} AND A.INPT_MST_SRNO = B.INPT_MST_SRNO /* 심사마스터일련번호 */ AND A.INPT_TASK_ID = B.INPT_TASK_ID /* 심사테스크아이디 */ AND A.AI_INPT_ALT_YN = 'Y' /* AI심사ALERT유무 */ ) A GROUP BY A.INPT_MST_SRNO, /* 심사마스터일련번호 */ A.INPT_BL_GRP_NO, /* 심사BL그룹번호 */ A.IMEX_HIS_CD /* 수출입명세코드 */ ) Z WHERE Y.AI_INPT_GRP_CD = '100' /* AI심사그룹코드 */ AND Y.AI_INPT_CMN_CD = X.IMEX_HIS_CD /* 수출입명세코드 */ AND X.INPT_MST_SRNO = Z.INPT_MST_SRNO (+) /* 심사마스터일련번호 */ AND X.INPT_BL_GRP_NO = Z.INPT_BL_GRP_NO (+) /* 심사BL그룹번호 */ AND X.IMEX_HIS_CD = Z.IMEX_HIS_CD (+) /* 수출입명세코드 */ AND X.RN = 1 ORDER BY X.INPT_BL_GRP_NO, Y.AI_INPT_SORT_SEQ

/* TotalText 항목심사 image coordinates */ WITH W_CSPD002TG AS ( SELECT A.INPT_MST_SRNO , A.INPT_BL_GRP_NO , A.IMEX_HIS_CD , B.INPT_ATMC_BIZ_DSCD , A.INPT_TASK_ID , A.INPT_ELMT_ID FROM CSPD002TG A JOIN CSPD001TM B ON B.INPT_MST_SRNO = A.INPT_MST_SRNO WHERE A.INPT_MST_SRNO = #{inptMstSrno} ) SELECT 'TOTAL' AS SPD_KIND , A.INPT_MST_SRNO , B.INPT_BL_GRP_NO , B.IMEX_HIS_CD , B.INPT_TASK_ID , B.INPT_ELMT_ID , A.AI_INPT_TOTALTEXT_SRNO , NULL AS INPT_SANCTION_NO , 'N' AS ITM_INPT_NACRD_YN , NVL(A.AI_INPT_ALT_YN, 'N') AS AI_INPT_ALT_YN , CASE WHEN A.ITM_INPT_XAXIS_STA_CRDN_CN IS NULL THEN '[]' ELSE '[' || A.ITM_INPT_XAXIS_STA_CRDN_CN || ',' || A.ITM_INPT_YAXIS_STA_CRDN_CN || ',' || A.ITM_INPT_XAXIS_END_CRDN_CN || ',' || A.ITM_INPT_YAXIS_END_CRDN_CN || ']' END AS ITEM_COORD_DINATES FROM CSPD003TF A JOIN W_CSPD002TG B ON B.INPT_MST_SRNO = A.INPT_MST_SRNO AND B.INPT_TASK_ID = A.INPT_TASK_ID
UNION ALL
SELECT 'SANC' AS SPD_KIND , A.INPT_MST_SRNO , B.INPT_BL_GRP_NO , B.IMEX_HIS_CD , B.INPT_TASK_ID , B.INPT_ELMT_ID , NULL AS AI_INPT_TOTALTEXT_SRNO , A.INPT_SANCTION_NO , NVL(A.ITM_INPT_NACRD_YN, 'N') AS ITM_INPT_NACRD_YN , NVL(A.AI_INPT_ALT_YN, 'N') AS AI_INPT_ALT_YN , CASE WHEN A.ITM_INPT_XAXIS_STA_CRDN_CN IS NULL THEN '[]' ELSE '[' || A.ITM_INPT_XAXIS_STA_CRDN_CN || ',' || A.ITM_INPT_YAXIS_STA_CRDN_CN || ',' || A.ITM_INPT_XAXIS_END_CRDN_CN || ',' || A.ITM_INPT_YAXIS_END_CRDN_CN || ']' END AS ITEM_COORD_DINATES FROM CSPD004TF A JOIN W_CSPD002TG B ON B.INPT_MST_SRNO = A.INPT_MST_SRNO AND B.INPT_TASK_ID = A.INPT_TASK_ID JOIN CSPD112TI C ON C.AI_INPT_GRP_CD = CASE WHEN B.INPT_ATMC_BIZ_DSCD IN ('1', '01') THEN '240' WHEN B.INPT_ATMC_BIZ_DSCD IN ('2', '02') THEN '230' ELSE '' END AND C.AI_INPT_CMN_CD = TO_CHAR(A.INPT_SANCTION_NO)

