mapper.select:
/* 상세팝업 접근권한 체크 */
/* 1011 - 심사상세 및 수기처리(심사자) */
/* 2011 - 심사-심사상세 및 결재처리(결재자) */
/* 2012 - QA-심사상세 및 결재처리(결재자) */
/* 3011 - 심사상세 및 자체점검처리(QA) */
/* 심사상세 팝업 접근 권한 체크 - 접근가능시 1, 접근권한 없으면 0 반환 */
SELECT NVL(SUM(A.RESULT),0)
FROM (
	SELECT 0 AS RESULT FROM DUAL


		/* 1) 심사자 심사상세 팝업인 경우 */
		UNION ALL
		SELECT CASE WHEN NVL(COUNT(*),0) > 0 THEN 1 ELSE 0 END AS RESULT
		FROM CSPD001TM
		WHERE INPT_MST_SRNO = #{inptMstSrno}
		OR AI_INPT_SNPE_ENO = #{schUserNo}
		OR QLAS_CRPE_ENO = #{schUserNo}



		/* 2) 결재자 심사상세 팝업인 경우 */
		UNION ALL
		SELECT CASE WHEN NVL(COUNT(*),0) > 0 THEN 1 ELSE 0 END AS RESULT
		FROM CSPD001TM
		WHERE INPT_MST_SRNO = #{inptMstSrno}
		OR AI_INPT_SNPE_ENO = #{schUserNo}
		OR QLAS_CRPE_ENO = #{schUserNo}



		/* 3) QA 심사상세 팝업인 경우 */
		UNION ALL
		SELECT CASE WHEN NVL(COUNT(*),0) > 0 THEN 1 ELSE 0 END AS RESULT
		FROM CSPD001TM
		WHERE INPT_MST_SRNO = #{inptMstSrno}
		OR AI_INPT_SNPE_ENO = #{schUserNo}
		OR QLAS_CRPE_ENO = #{schUserNo}

) A

