mapper.select:
SELECT NVL(MAX(AI_INPT_ACVT_STS_CD) KEEP(
		                        DENSE_RANK FIRST  
		                        ORDER BY AI_INPT_PRG_SRNO DESC
		                        ), '00') AS AI_INPT_ACVT_STS_CD
  FROM CSPD008TH
 WHERE INPT_MST_SRNO = #{inptMstSrno}

SELECT A.INPT_MST_SRNO
	  , A.INPT_TASK_ID
	  , B.INPT_BL_GRP_NO 
FROM CSPD004TF A
	, CSPD002TG B
WHERE A.INPT_TASK_ID = B.INPT_TASK_ID
AND A.INPT_MST_SRNO = B.INPT_MST_SRNO
AND A.INPT_MST_SRNO = #{inptMstSrno} 
AND B.IMEX_HIS_CD = #{imexHisCd}  
AND A.INPT_SANCTION_NO = #{inptSanctionNo} 
AND A.INPT_SANCTION_DAT_TXT = #{inptSanctionDatTxt}

