AND ( ITM_INPT_HNDG_INP_DAT_TXT IS NOT NULL OR ITM_INPT_HNDG_ADD1_TXT IS NOT NULL OR ITM_INPT_HNDG_ADD2_TXT IS NOT NULL OR ITM_INPT_HNDG_ADD3_TXT IS NOT NULL )

