/* 그룹내 SafeWatch = 'Y' 인 해당 Sanction 이미지 조회 */
SELECT A.INPT_TASK_ID
FROM  CSPD004TF A
	, CSPD002TG B
WHERE A.INPT_MST_SRNO = B.INPT_MST_SRNO
AND A.INPT_TASK_ID = B.INPT_TASK_ID
AND A.SAFEWATCH_ITM_YN  = 'Y'
AND A.INPT_MST_SRNO = #{inptMstSrno}  
AND A.INPT_SANCTION_NO =  #{inptSanctionNo}				
AND B.INPT_BL_GRP_NO = #{inptBlGrpNo}
AND ROWNUM = 1

/* 그룹내 가장 빠른 이미지 조회 */
SELECT TO_CHAR(MIN(TO_NUMBER(INPT_TASK_ID)))
FROM  CSPD002TG
WHERE INPT_MST_SRNO = #{inptMstSrno}  	
AND INPT_BL_GRP_NO = #{inptBlGrpNo}

/* 그륩내 입력 Sanction번호 정보 존재 여부 확인(insert/update 판단) */
SELECT INPT_SANCTION_NO
FROM  CSPD004TF
WHERE INPT_MST_SRNO = #{inptMstSrno}  
AND INPT_TASK_ID = #{inptTaskId}	
AND INPT_SANCTION_NO =  #{inptSanctionNo}
